package main

import "fmt"

// ReverseIntSlice reverses the order of elements in the given integer slice in place.
func ReverseIntSlice(nums []int) {
    // Initialize two pointers: 'left' at the start and 'right' at the end of the slice.
    left := 0
    right := len(nums) - 1

    // Continue swapping elements until the left pointer crosses or meets the right pointer.
    for left < right {
        // 1. Store the value at the left index temporarily (to avoid losing it).
        temp := nums[left]

        // 2. Replace the element at the left index with the element at the right index.
        nums[left] = nums[right]

        // 3. Replace the element at the right index with the stored temporary value.
        nums[right] = temp

        // Move the pointers inward
        left++
        right--
    }
}

